def possible(*, exact_mouths=False, curvature_limits=False):
    name = 'Prochitecture Streets / Conservative endpoint rejection v1'
    if exact_mouths:name += ' / Exact mouths'
    if curvature_limits:name += ' / Curvature limit'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g = c.Graph(name)
    g.socket('Geometry','NodeSocketGeometry')
    g.socket('Input Valid','NodeSocketBool')
    g.socket('Margin','NodeSocketFloat',default=.025)
    g.socket('Possible','NodeSocketBool','OUTPUT')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    src=inp.outputs['Geometry'];count=c._count(g,src)
    margin=c.V(g,inp.outputs['Margin'])
    valid=c.V(g,inp.outputs['Input Valid'])*g.math('GREATER_THAN',count,.5)*g.math('LESS_THAN',count,clearance.MAX_SAMPLES+.5)
    valid*=g.math('GREATER_THAN',margin,0.)*g.math('LESS_THAN',margin,.25)
    index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    queries=c._store(g,src,'_clearance_rejection_index',index,'INT')
    t=c.named(g,'st_cg_t')
    endpoint=g.math('LESS_THAN',t,1e-7)+g.math('GREATER_THAN',t,1.-1e-7)
    queries=c._select(g,queries,endpoint)
    queries=clearance.boundary._empty(g,queries,valid)
    ri=g.node('GeometryNodeForeachGeometryElementInput','Check prescribed endpoints against every original peer')
    ro=g.node('GeometryNodeForeachGeometryElementOutput');ro.domain='POINT'
    ro.generation_items.clear();ro.main_items.new('BOOLEAN','Compatible')
    ri.pair_with_output(ro)
    g.bind(queries,ri.inputs['Geometry'])
    at=c._read(g,queries,'_clearance_rejection_index',ri.outputs['Index'],'INT')
    own=c._read(g,src,'st_cg_nominal',at)
    owner=c._read(g,src,'st_cg_owner',at,'INT')
    point=c._vec(g,c._sample(g,src,g.position(),at,'FLOAT_VECTOR'))
    distance=c._length(g,c._sub(c._vec(g,g.position()),point))
    other=c.named(g,'st_cg_nominal')
    candidate=distance*own/g.math('MAXIMUM',own+other,1e-8)
    if exact_mouths:
        shared=clearance._same_mouth(g,src,owner,c._read(g,src,'st_cg_t',at))
        candidate=c.choose(g,shared,own,candidate)
    eligible=1.-g.math('COMPARE',owner,c.named(g,'st_cg_owner','INT'))
    cap=c._stat(g,src,c.choose(g,eligible,candidate,1e8))
    if curvature_limits:
        cap=g.math('MINIMUM',cap,c._read(g,src,'st_cg_curvature_cap',at))
    # Reuse the original comparisons, endpoint tolerance and collapsed-band
    # rule. Reimplementing this as a looser geometric heuristic is unsafe.
    _,good=clearance._depth_query(g,src,at,own,cap,margin,directional=False)
    g.bind(good,ro.inputs['Compatible'])
    all_good=c._stat(g,ro.outputs['Geometry'],ro.outputs['Compatible'])
    # Malformed tables without endpoints cannot be rejected by this proof.
    # They must receive the preceding complete evaluation and its exact result.
    result=valid*c.choose(g,g.math('GREATER_THAN',c._count(g,queries),.5),all_good,True,'BOOLEAN')
    g.bind(result,out.inputs['Possible'])
    g.g['st_clearance_endpoint_rejection']=1
    return g.g


def guarded(original):
    """Copy the adaptive selector, preserving both existing allocator groups."""
    prefix='Prochitecture Streets / Adaptive sampled profile clearance'
    if not original.name.startswith(prefix):raise ValueError('Expected adaptive clearance selector')
    if original.get('st_clearance_endpoint_rejection'):
        raise ValueError('Endpoint rejection already installed')
    result=original.copy()
    result.name='Prochitecture Streets / Rejection-gated clearance / '+hashlib.sha256(original.name.encode()).hexdigest()[:16]
    preferred,=[n for n in result.nodes if n.type=='GROUP' and n.node_tree and
                n.node_tree.name.startswith('Prochitecture Streets / Sampled weighted profile clearance')]
    # Recognize only the unmodified conservative kernel whose equations the
    # proof uses. Unknown options must be reviewed before extending this gate.
    allowed={'Attribute map v1','Exact mouth contacts v1','Curvature limit v1'}
    tokens=preferred.node_tree.name.split(' / ')[2:]
    if set(tokens)-allowed:raise ValueError('Unknown conservative kernel options: '+repr(tokens))
    g=c.Graph.__new__(c.Graph);g.g=result;g.count=len(result.nodes);g.frame=None
    destinations=[link.to_socket for link in preferred.outputs['Valid'].links]
    if not destinations:raise ValueError('Unused conservative clearance validity')
    proof=g.node('GeometryNodeGroup','Reject only an already incompatible conservative profile')
    proof.node_tree=possible(exact_mouths='Exact mouth contacts v1' in tokens,
                             curvature_limits='Curvature limit v1' in tokens)
    for key in ('Geometry','Input Valid','Margin'):
        socket=preferred.inputs[key]
        if socket.is_linked:
            link,=socket.links;g.bind(link.from_socket,proof.inputs[key])
        else:proof.inputs[key].default_value=socket.default_value
    # A lazy switch matters here: multiplication would still evaluate the
    # complete rejected branch. Geometry selection already uses this boolean.
    use=c.choose(g,proof.outputs['Possible'],preferred.outputs['Valid'],False,'BOOLEAN')
    for socket in destinations:g.bind(use,socket)
    result['st_clearance_endpoint_rejection']=1
    return result


def copy_graph(root):
    """Private comparison retaining shared group identity and original data."""
    memo={};changes=[]
    def visit(tree):
        if tree in memo:return memo[tree]
        if tree.name.startswith('Prochitecture Streets / Adaptive sampled profile clearance'):
            result=guarded(tree)
            changes.append(dict(original=tree.name,candidate=result.name,
                                proof='Exact conservative endpoint rejection; no new acceptance'))
        else:
            replacements=[(n.name,visit(n.node_tree)) for n in tree.nodes if n.type=='GROUP' and n.node_tree]
            replacements=[(name,child) for name,child in replacements if child!=tree.nodes[name].node_tree]
            result=tree.copy() if replacements else tree
            for name,child in replacements:assign_group(result.nodes[name],child)
        memo[tree]=result;return result
    multiple=isinstance(root,(list,tuple))
    result=[visit(tree) for tree in root] if multiple else visit(root)
    if not changes:raise ValueError('No adaptive clearance selectors found')
    return result,changes
